    FileSeal.prototype._readTempFile=function (param){
        var seq=new $m.Seq();
        var that=this;
        var middleware=null;
        seq.then(function (){
            that._getMiddleware({
                success: function (m){
                    middleware=m;
                    seq.resolve(m);
                },
                fail: function (e){
                    seq.reject(e);
                }
            })
        }).then(function (seq){
            middleware.readFile({
                file: param.outFile,
                dataFormat: "Base64",
                success: function (data){
                    seq.resolve(data)
                },
                fail: function (e){
                    seq.reject(e);
                }
            })
        }).then(function (seq,data){
            //删除临时文件，不用等待完成
            if(param.inFile){
                middleware.removeFile({
                    fileName: param.inFile,
                })
            }
            middleware.removeFile({
                fileName: param.outFile,
            })
            seq.resolve(data)
        }).then(function (seq,data){
            $m.util.success(param,data);
        }).onerror(function (e){
            $m.util.fail(param,e);
        }).run();
    }

    FileSeal.prototype._removeTempFile=function (param){
        var seq=new $m.Seq();
        var that=this;
        var middleware=null;
        seq.then(function (){
            that._getMiddleware({
                success: function (m){
                    middleware=m;
                    seq.resolve(m);
                },
                fail: function (e){
                    seq.reject(e);
                }
            })
        }).then(function (seq){
            //删除临时文件，不用等待完成
            middleware.removeFile({
                fileName: param.file,
            })
            seq.resolve()
        }).then(function (seq){
            $m.util.success(param,null);
        }).onerror(function (e){
            $m.util.fail(param,e);
        }).run();
    }

