    FileSeal.prototype.signOfd=function (param) {
        var seq=new $m.Seq();
        var that=this;
        seq.then(function (){
            if(!param.multiSeal){
                if(param.command.sealType===0){
                    //签章
                    if(that.context.substr(that.context.length-3)==="oes"){
                        that._assertSealSelected({
                            context: that.context,
                            command: param.command,
                            success:function (sealSn){
                                param.command.sealSn=sealSn;
                                seq.resolve();
                            },
                            fail:function (e){
                                seq.reject(e);
                            }
                        })
                    } else {
                        that._assertSealLogined({
                            context: that.context,
                            command: param.command,
                            password: param.password,
                            success:function (sealSn){
                                param.command.sealSn=sealSn;
                                seq.resolve();
                            },
                            fail:function (e){
                                seq.reject(e);
                            }
                        })
                    }
                }
                else {
                    //签批
                    if(!param.command.sign){
                        seq.reject(new Error("缺少签批参数，sign对象为空"))
                        return
                    }
                    that._assertCertLogined({
                        command: param.command,
                        password: param.password,
                        success:function (certId){
                            param.command.sign.certSubjectId=certId;
                            seq.resolve();
                        },
                        fail:function (e){
                            seq.reject(e);
                        }
                    })
                }
            }else{
                seq.resolve()
            }
        }).then(function (){
            if(param.inData){
                //字符串输入
                that._writeTempFile({
                    inData: param.inData,
                    fileType: "ofd",
                    success: function (ret){
                        param.inFile=ret.inFile
                        param.outFile=ret.outFile
                        seq.resolve()
                    },
                    fail: function (e){
                        seq.reject(e)
                    }
                })
            } else {
                seq.resolve()
            }
        }).then(function (){
            param.command=JSON.stringify(param.command);
            var p={
                success: function (){
                    seq.resolve()
                },
                fail: function (e){
                    seq.reject(e)
                }
            };
            $m.util.setAttrs(p,param,["command", "multiSeal", "password", "inFile", "outFile", "inUrl", "outUrl",
                "partName", "fileName", "certVerify", "sealVerify", "enableTimeStamp"])
            that.imp.signOfd(p);
        }).then(function (){
            if(param.inData){
                that._readTempFile({
                    outFile: param.outFile,
                    inFile: param.inFile,
                    success: function (d){
                        $m.util.success(param,d);
                    },
                    fail: function (e){
                        $m.util.fail(param,e);
                    }
                })
            } else {
                $m.util.success(param,null);
            }
        }).onerror(function (e){
            $m.util.fail(param,e);
        }).run();
    };

