    //将函数转化为Promise
    function toPromise(func,param){
        return new Promise(function (resolve,reject) {
            if(!param){
                param={}
            }
            param.success=function (ret) {
                resolve(ret);
            };
            param.fail=function (msg) {
                reject(new Error(msg));
            };
            func(param);
        });
    }

    function toPromiseWithObj(obj,func,param){
        return new Promise(function (resolve,reject) {
            if(!param){
                param={}
            }
            param.success=function (ret) {
                resolve(ret);
            };
            param.fail=function (msg) {
                reject(new Error(msg));
            };
            func.call(obj,param);
        });
    }

