/*
* @requires  ../util/websocket.js
*/

var HebcaMiddleware = HebcaMiddleware || {};
(function($m) {

    function SealWebJsWebsocket(param) {
        this.host="ws://localhost:17212/test";
        this.websocket=new $m.WebSocketWrapper(this.host);
        this.websocket.connect(param);
    }

    SealWebJsWebsocket.prototype.setEventCallback=function(m,callback){
        this.middlewareObj=m;
        this.websocket.setEventCallback(m,callback);
    };

    SealWebJsWebsocket.prototype.getCertList=function (param) {
        var name="getCertList";
        var that=this;

        this.websocket.sendMessage({
            fun: 'GetCertList',
            param: '',
            success: function (json) {
                that.websocket.onSuccess(name, param, json);
            },
            fail: function (e) {
                that.websocket.onFail(name, param, e);
            }
        });
    };

    SealWebJsWebsocket.prototype.unUiLogin=function (param) {
        var name="unUiLogin";
        var that=this;

        var p={};
        $m.util.setAttrs(p,param,["certSN", "password"]);

        this.websocket.sendMessage({
            fun: 'UnUICertLogin',
            param: JSON.stringify(p),
            success: function (json) {
                that.websocket.onSuccess(name, param, json);
            },
            fail: function (e) {
                that.websocket.onFail(name, param, e);
            }
        });
    };

    SealWebJsWebsocket.prototype.unUiLogout=function (param) {
        var name="unUiLogout";
        var that=this;

        var p={};
        $m.util.setAttrs(p,param,["certSN"]);

        this.websocket.sendMessage({
            fun: 'UnUICertLogout',
            param: JSON.stringify(p),
            success: function (json) {
                that.websocket.onSuccess(name, param, json);
            },
            fail: function (e) {
                if ( e.message === '用户没有登录'){
                    that.websocket.onSuccess(name, param, e);
                } else {
                    that.websocket.onFail(name, param, e);
                }


            }
        });
    };

    SealWebJsWebsocket.prototype.digest=function (param) {
        var name="digest";
        var that=this;

        var p={};
        $m.util.setAttrs(p,param,["certSN", "b64data", "digestalg"]);

        this.websocket.sendMessage({
            fun: 'Digest',
            param: JSON.stringify(p),
            success: function (json) {
                that.websocket.onSuccess(name, param, json);
            },
            fail: function (e) {
                that.websocket.onFail(name, param, e);
            }
        });
    };

    SealWebJsWebsocket.prototype.unUiSign=function (param) {

        var name="unUiSign";
        var that=this;

        try {
            var lenTotal = param.b64data.length;
            var lenPerPacketData = 10240; //10K
            var subPacketCnt = Math.ceil(lenTotal / lenPerPacketData);
            var curPacketIndex = 0;

            that._unUiSign_SubPacket_Do({
                curPacketIndex : curPacketIndex,
                subPacketCnt : subPacketCnt,
                lenPerPacketData : lenPerPacketData,
                b64data : param.b64data,
                certSN : param.certSN,
                success : param.success,
                fail : param.fail
            });
        } catch (e) {
            that.websocket.onFail(name, param, e);
        }
    };

    SealWebJsWebsocket.prototype._unUiSign_SubPacket_Do=function (param) {
        var name="unUiSign";
        var that=this;


        var subB64 = param.b64data.substr(param.curPacketIndex * param.lenPerPacketData, param.lenPerPacketData);
        var p = {
            "subPacketCnt": param.subPacketCnt.toString(),
            "curPacketIndex": param.curPacketIndex.toString(),
            "b64data": subB64.toString(),
            "certSN": param.certSN.toString()
        }

        this.websocket.sendMessage({
            fun: 'UnUISign',
            param: JSON.stringify(p),
            success: function (json) {
                if (param.curPacketIndex>=param.subPacketCnt-1){
                    that.websocket.onSuccess(name, param, json);
                }
                else{
                    param.curPacketIndex = param.curPacketIndex + 1;
                    that._unUiSign_SubPacket_Do({
                        curPacketIndex : param.curPacketIndex,
                        subPacketCnt : param.subPacketCnt,
                        lenPerPacketData : param.lenPerPacketData,
                        b64data : param.b64data,
                        certSN : param.certSN,
                        success : param.success,
                        fail : param.fail
                    });
                }
            },
            fail: function (e) {
                that.websocket.onFail(name, param, e);
            }
        });

    };


    function SealWebJsFaceWebsocket(param) {
        this.host="ws://localhost:17818/test";
        this.websocket=new $m.WebSocketWrapper(this.host);
        this.websocket.connect(param);
    }

    SealWebJsFaceWebsocket.prototype.setEventCallback=function(m,callback){
        this.middlewareObj=m;
        this.websocket.setEventCallback(m,callback);
    };

    SealWebJsFaceWebsocket.prototype.getCameraNum=function (param) {
        var name="getCameraNum";
        var that=this;

        this.websocket.sendMessage({
            fun: 'GetCameraNum',
            param: '',
            success: function (json) {
                that.websocket.onSuccess(name, param, json);
            },
            fail: function (e) {
                if (e.message === '连接证书服务失败'){
                    that.websocket.onFail(name, param, new Error('连接人脸认证服务失败'));
                } else
                    that.websocket.onFail(name, param, e);
            }
        });
    };

    SealWebJsFaceWebsocket.prototype.openCamera=function (param) {
        var name="openCamera";
        var that=this;

        var p={};
        $m.util.setAttrs(p,param,["indexColor", "indexInfrar"]);

        this.websocket.sendMessage({
            fun: 'OpenCamera',
            param: JSON.stringify(p),
            success: function (json) {
                that.websocket.onSuccess(name, param, json);
            },
            fail: function (e) {
                that.websocket.onFail(name, param, e);
            }
        });
    };

    SealWebJsFaceWebsocket.prototype.closeCamera=function (param) {
        var name="closeCamera";
        var that=this;

        var p={};
        $m.util.setAttrs(p,param,["indexColor", "indexInfrar"]);

        this.websocket.sendMessage({
            fun: 'CloseCamera',
            param: JSON.stringify(p),
            success: function (json) {
                that.websocket.onSuccess(name, param, json);
            },
            fail: function (e) {
                that.websocket.onFail(name, param, e);
            }
        });
    };

    SealWebJsFaceWebsocket.prototype.faceImageData=function (param) {
        var name="faceImageData";
        var that=this;

        this.websocket.sendMessage({
            fun: 'FaceImageData',
            param: '',
            success: function (json) {
                that.websocket.onSuccess(name, param, json);
            },
            fail: function (e) {
                that.websocket.onFail(name, param, e);
            }
        });
    };



    $m.SealWebJsWebsocket=SealWebJsWebsocket;

    $m.SealWebJsFaceWebsocket=SealWebJsFaceWebsocket;
})(HebcaMiddleware);
