    /**
     * 刷新授权码，如果授权码未过期，则使用缓存的授权码，如果已经过期需要重新认证
     * @param param {
     *     certSubjectId,
     * }
     *
     * @private
     */
    SealWebJs.prototype._refreshAuthCodePromise = function (param) {
        var that = this;
        var result_authCode = '';

        return new Promise((resolve, reject) => {
            result_authCode = that._getAuthCodeCache({
                certSubjectId: param.certSubjectId
            });
            if (result_authCode.length > 0) {
                resolve();
            } else {
                that._getHttpHeaderPromise()
                    .then(function (resultHeader) {
                        var authTypes_Url = that._getAuthTypesURL();
                        return that._getAuthTypesPromise({
                            'url': authTypes_Url,
                            'header': resultHeader,
                            'data': ''
                        });
                    })
                    .then(resultAuthTypes => {
                        var authTypes = eval(resultAuthTypes);
                        var authTypesNames = ['人脸认证', '证书密码认证', '短信验证码认证'];
                        var items = [];

                        for (oneType in authTypes) {
                            var item = {};
                            item.type = authTypes[oneType];
                            item.showName = authTypesNames[authTypes[oneType] - 1];
                            items.push(item);
                        }
                        return that._SelectAuthType({
                            authTypes: items
                        });
                    })
                    .then(authType => {
                        param.selectedAuthType = authType;
                        return new Promise((resolve, reject) => {
                            if (authType === 0) {
                                resolve('');

                            } else if (authType === 1) {
                                // TODO:人脸认证
                                // 弹出认证界面（开始，采集，结束）
                                // 点击开始认证按钮
                                // 判断是否有摄像头，打开摄像头，手动采集，手动结束；
                                if (that.isHasClient === true) {
                                    if ($m._ui && $m._ui.authCertFace) {
                                        $m._ui.authCertFace({
                                            certSubjectId: param.certSubjectId,
                                            'webJsObj': that,
                                            success: function (facepicB64) {
                                                resolve(facepicB64);
                                            },
                                            fail: function (e) {
                                                reject(e);
                                            }
                                        });

                                    } else {
                                        reject(new Error('没有定义人脸认证界面'));
                                    }
                                } else {
                                    reject(new Error('没有启动人脸认证服务'));
                                }
                            } else if (authType === 2) {
                                // 证书密码认证
                                if ($m._ui && $m._ui.authCertPassWord) {
                                    $m._ui.authCertPassWord({
                                        certSubjectId: param.certSubjectId,
                                        success: function (password) {
                                            resolve(password);
                                        },
                                        fail: function (e) {
                                            reject(e);
                                        }
                                    })
                                } else {
                                    reject(new Error('没有定义证书密码认证界面'));
                                }
                            } else if (authType === 3) {
                                // 短信验证码认证
                                that._getAuthVeriyCode({
                                    certSubjectId: param.certSubjectId
                                }).then(resultcode => {
                                    if ($m._ui && $m._ui.authCertVerifyCode) {
                                        $m._ui.authCertVerifyCode({
                                            certSubjectId: param.certSubjectId,
                                            success: function (verifyCode) {
                                                resolve(verifyCode);
                                            },
                                            fail: function (e) {
                                                reject(e);
                                            }
                                        })
                                    } else {
                                        reject(new Error('没有定义短信认证界面'));
                                    }
                                }).catch(error => {
                                    reject(error);
                                });
                            }
                        });
                    })
                    .then(authData => {
                        param.authData = authData;
                        return that._getAuthCode({
                            certSubjectId: param.certSubjectId,
                            type: param.selectedAuthType,
                            data: param.authData
                        });

                    })
                    .then(resultAuthCode => {
                        resolve();
                    })
                    .catch(error => {
                        reject(error);
                    });
            }
        });
    }

    /**
     * 获取授权码
     * @param param{
     *     certSubjectId,
     *     type, 0，1，2，3，；0：时，说明不需要获取授权码，直接返回。
     *     data,
     * }
     * @private
     */
    SealWebJs.prototype._getAuthCode = function (param) {
        var that = this;
        return new Promise((resolve, reject) => {
            if (param.type === 0) {
                resolve('');
            } else {
                that._getHttpHeaderPromise()
                    .then(function (resultHeader) {
                        var authCodeURL = that._getAuthCodeURL();
                        paramsauthCode = that._getParamsAuthCode_RequestData(param);
                        return that._authCodePromise({
                            'url': authCodeURL,
                            'header': resultHeader,
                            'data': paramsauthCode
                        });
                    })
                    .then(function (resultAuthCode) {
                        var time_now_seconds = Math.floor(Date.now() / 1000);
                        that.m_g_cloud_authCode = resultAuthCode.authcode;
                        that.m_g_cloud_expires = time_now_seconds + resultAuthCode.expiresIn;
                        var a ={certSubjectId: param.certSubjectId, expires: that.m_g_cloud_expires, authcode: that.m_g_cloud_authCode};
                        that.m_g_authCode_ALL.push(a);
                        resolve(resultAuthCode);
                    })
                    .catch(error => {
                        reject(error);
                    });

            }

        });
    }


    /**
     * 获取短信验证码
     * @param param｛
     * certSubjectId，证书唯一项，用于获取当前证书对应的验证码
     * ｝
     * @returns {Promise<unknown>}
     * @private
     */
    SealWebJs.prototype._getAuthVeriyCode = function (param) {
        var that = this;
        return new Promise((resolve, reject) => {
            that._getHttpHeaderPromise()
                .then(function (resultHeader) {
                    var authVerifyCodeURL = that._getAuthVerifyCodeURL();
                    var paramsauthCode = that._getParamsAuthVerifyCode_RequestData(param);
                    return that._authVerifyCodePromise({
                        'url': authVerifyCodeURL,
                        'header': resultHeader,
                        'data': paramsauthCode
                    });
                })
                .then(function (resultAuthCode) {
                    resolve(resultAuthCode);
                })
                .catch(error => {
                    reject(error);
                });


        });
    }

    /**
     * 获取缓存的authCode
     * @returns {string}
     * @private
     */
    SealWebJs.prototype._getAuthCodeCache = function (param) {
        var that = this;
        var result_authCode = "";

        var b= that.m_g_authCode_ALL.find((a)=>a.certSubjectId === param.certSubjectId);
        if ( b === undefined )
            return result_authCode;
        else {
            var time_now_seconds = Math.floor(Date.now() / 1000);
            if (time_now_seconds >= b.expires) {
                for (var i=0; i<that.m_g_authCode_ALL.length; i++){
                    if (that.m_g_authCode_ALL[i].certSubjectId === b.certSubjectId){
                        that.m_g_authCode_ALL.splice(i,1);
                    }
                }
                return result_authCode;
            } else {
                return b.authcode;
            }
        }
    }

