    /**
     * 列章执行函数
     * @param param
     * {
     *     url:
     *     header:
     *     data:
     * }
     */
    SealWebJs.prototype._listSealPromise = function (param) {
        var that = this;


        var sealList = [];


        return new Promise((resolve, reject) => {
            $m.axios({
                method: 'post',
                url: param.url,
                headers: param.header,
                data: param.data,
                transformRequest: [function (data) {
                    var ret = '';
                    for (var i in data) {
                        ret += encodeURIComponent(i) + '=' + encodeURIComponent(data[i]) + "&";
                    }
                    return ret;
                }],

            }).then(resp => {
                if (that.cloudEnable) {
                    var res_code = resp.data.code;
                    if (res_code === 0) {
                        sealList = resp.data.data;
                    } else {
                        throw new Error(resp.data.message);
                    }

                } else {
                    var res_code = resp.headers['result-code'];
                    if (res_code === '0') {
                        for (var i = 0; i < resp.data.length; i++) {
                            var seal = {
                                sealSn: '',
                                sealName: '',
                                sealStatus: '',
                                sealStandard: '',
                                certSn: ''
                            };
                            seal.sealSn = resp.data[i].sealSN;
                            seal.sealName = resp.data[i].sealName;
                            seal.certSn = resp.data[i].certID;

                            sealList.push(seal);
                        }
                    } else {
                        throw new Error(resp.data.errorMessage);
                    }
                }
                resolve(sealList);
            }).catch(error => {
                reject(error);
            });

        });

    }

