    /**
     * 选择证书，如果证书列表为空，则报错，如果证书列表个数1个，则直接返回，否则弹出选择界面
     * @param param
     * {
     *     certs：证书列表对象
     *     success：function(cert){}
     *     fail：function(e){}
     * }
     */
    MiddlewareUiBootstrap.prototype.selectCert = function (param) {
        var selectControl = '<select class="form-control" name="certChooseSelect">';
        for (var i = 0; i < param.certs.length; i++) {
            selectControl += '<option value="' + i + '" >' + param.certs[i].subject.cn + '</option>';
        }
        selectControl += '</select>';

        var content = '<form class="form-horizontal" role="form" >' +
            '<div class="form-group">' +
            '<label for="itemName" class="col-sm-2 control-label">证书:</label>' +
            '<div class="col-sm-8" >' +
            selectControl +
            '</div>' +
            '</div>' +
            '</form>';

        var m = '<div class="modal fade" id="certChooseDialog" tabindex="-1" role="dialog" aria-labelledby="myModalLabel" aria-hidden="true" style="z-index: 9999; ">' +
            '<div class="modal-dialog">' +
            '<div class="modal-content">' +
            '<div class="modal-header">' +
            '<button type="button" class="close" data-dismiss="modal" aria-hidden="true">&times;</button>' +
            '<h4 class="modal-title" id="myModalLabel">选择证书</h4>' +
            '</div>' +
            '<div class="modal-body">' + content + '</div>' +
            '<div class="modal-footer">' +
            '<button type="button" class="btn btn-primary" id="certChooseDialogOk">确 定</button>' +
            '<button type="button" class="btn btn-default" data-dismiss="modal">取 消</button>' +
            '</div>' +
            '</div>' +
            '</div>' +
            '</div>';

        $("body").append(m);
        var clickOk = false;
        $('#certChooseDialog').on('hide.bs.modal',
            function () {
                $("#certChooseDialog").remove();
                if (clickOk == false) {
                    if (param.fail)
                        param.fail(new Error("用户取消操作"));
                }
            });
        $("#certChooseDialogOk").click(function () {
            var selectIndex = $("#certChooseDialog [name=certChooseSelect]").val();
            clickOk = true;
            $("#certChooseDialog").modal('hide');
            param.success(param.certs[selectIndex]);
        });
        $("#certChooseDialog").modal('show');
    };

