    /**
     * 进度
     * @param param
     * {
     *     title：
     *     currentLength:
     *     allLength
     *     success：function(){}
     *     fail：function(e){}
     * }
     */
    MiddlewareUiBootstrap.prototype.progress = function (param) {
        var finish = false;
        if (param.allLength <= 0) {
            param.success();
            return;
        }

        if (param.currentLength === 0) {
            var content = '<div class="progress">\n' +
                '    <div id="progressDialog-progressbar" class="progress-bar progress-bar-success" role="progressbar"' +
                '         aria-valuenow="60" aria-valuemin="0" aria-valuemax="100"' +
                '         style="width: 0%;">' +
                '    </div>' +
                '</div>';

            var m = '<div class="modal fade" id="progressDialog" tabindex="-1" role="dialog" aria-labelledby="myModalLabel" aria-hidden="true" style="z-index: 9999; ">' +
                '<div class="modal-dialog">' +
                '<div class="modal-content">' +
                '<div class="modal-header">' +
                '<button type="button" class="close" data-dismiss="modal" aria-hidden="true">&times;</button>' +
                '<h4 class="modal-title" id="progressDialog-label">' + param.title + '</h4>' +
                '</div>' +
                '<div class="modal-body">' + content + '</div>' +
                '<div class="modal-footer">' +
                '<button type="button" class="btn btn-default" data-dismiss="modal">取 消</button>' +
                '</div>' +
                '</div>' +
                '</div>' +
                '</div>';

            $("body").append(m);
            $('#progressDialog').on('hide.bs.modal',
                function () {
                    $("#progressDialog").remove();
                    if (finish == false) {
                        if (param.fail) {
                            param.fail(new Error("用户取消操作"));
                        }
                    }
                });
            $("#progressDialog").modal('show');
            if (param.success) {
                param.success();
            }
        } else if (param.currentLength === param.allLength) {
            finish = true;
            $('#progressDialog').off('hide.bs.modal');
            $("#progressDialog").modal('hide');
            $("#progressDialog").remove();
            $(".modal-backdrop,.fade,.in").remove();
            setTimeout(function () {
                if (param.success) {
                    param.success();
                }
            }, 100);

        } else {
            var p = param.currentLength * 100 / param.allLength;
            console.log(p);
            $("#progressDialog-progressbar").css("width", p + "%");
            if (param.success) {
                param.success();
            }
        }
    };

