    /**
     * 选择设备
     * @param param
     * {
     *     filter: array 过滤设备，可选
     *     excludeFilter：array 排查过滤，可选
     *     success：function(device){}
     *     fail: function(e){}
     * }
     */
    Middleware.prototype.selectDevice=function(param){
        if($m._ui && $m._ui.selectDevice){
            var seq=new $m.Seq();
            var that=this;
            seq.then(function () {
                //获取设备列表
                that.getDevices({
                    success:function (devices) {
                        seq.resolve(devices);
                    },
                    fail:function (e) {
                        seq.reject(e);
                    }
                });
            }).then(function (seq,devices) {
                //过滤选择证书
                devices=that._filterDevice(devices,param);
                if(devices.length===0){
                    seq.reject(new Error("没有找到设备"));
                }
                else if(devices.length===1){
                    seq.resolve(devices[0]);
                }
                else{
                    $m._ui.selectDevice({
                        devices: devices,
                        success:function (device) {
                            seq.resolve(device);
                        },
                        fail:function (e) {
                            seq.reject(e);
                        }
                    });
                }
            }).then(function (seq,device) {
                $m.util.success(param,device);
            }).onerror(function (e) {
                $m.util.fail(param,e);
            }).run();
        }
        else{
            this.imp.selectDevice(param);
        }
    };

    Middleware.prototype._addDeviceToArray=function(devices,device){
        for(var i=0;i<devices.length;i++){
            if(devices[i].deviceId===device.deviceId){
                return ;
            }
        }

        devices.push(device);
    };

    Middleware.prototype._removeDevice=function(devices,device){
        for(var i=0;i<devices.length;i++){
            if(devices[i].deviceId===device.deviceId){
                devices.splice(i,1)
            }
        }
    };

    Middleware.prototype._filterDevice=function(devices,param){
        if(devices.length===0)
            return devices;

        var filterDevices=[];
        var that=this;
        if(param.filter){
            devices.forEach(function (v) {
                for(var i=0;i<param.filter.length;i++){
                    if(param.filter[i]===v.deviceName){
                        that._addDeviceToArray(filterDevices,v);
                    }
                }
            });
        }
        else
        {
            filterDevices=devices;
        }

        if(param.excludeFilter){
            var todelete=[];
            filterDevices.forEach(function (v,index) {
                for(var i=0;i<param.excludeFilter.length;i++){
                    if(param.excludeFilter[i]===v.deviceName){
                        todelete.push(v);
                    }
                }
            });
            for(var i=0;i<todelete.length;i++){
                that._removeDevice(filterDevices,todelete[i])
            }

        }

        return filterDevices;
    };

    Middleware.prototype._assertSelectDevice=function (param,next){
        var that=this;
        if(!param.deviceId){
            this.selectDevice({
                success:function (device) {
                    param.deviceId=device.deviceId;
                    next();
                },
                fail:function (e) {
                    $m.util.fail(param,e);
                }
            });
        }
        else{
            next();
        }
    }

    Middleware.prototype._assertDeviceLogined=function (param,next){
        var that=this;
        this.loginDevice({
            deviceId: param.deviceId,
            password: param.password,
            success:function (deviceId) {
                if(!param.deviceId)
                    param.deviceId=deviceId
                next();
            },
            fail:function (e) {
                $m.util.fail(param,e);
            }
        })
    }

