    /**
     * 登录设备
     * @param param
     * {
     *     deviceId: 设备ID，可选，如果为空，则自动选择
     *     app: 应用名称，可选，默认KOAL_ECC_APP
     *     password： 密码
     *     success: function(deviceId){}
     *     fail: function(e){}
     * }
     */
    Middleware.prototype.loginDevice=function(param){
        var that=this;
        var seq=new $m.Seq();
        seq.then(function () {
            if(!param.deviceId){
                that.selectDevice({
                    success:function (device) {
                        param.deviceId=device.deviceId;
                        seq.resolve(device);
                    },
                    fail:function (e) {
                        seq.reject(e);
                    }
                })
            }
            else {
                that.getDevices({
                    success:function (devices) {
                        for(var i=0;i<devices.length;i++){
                            if(devices[i].deviceId===param.deviceId){
                                seq.resolve(devices[i]);
                                return
                            }
                        }

                        seq.reject(new Error("没有找到对应的设备"))
                    },
                    fail:function (e) {
                        seq.reject(e);
                    }
                })
            }
        }).then(function (seq,device){
            //判断是否已登录
            that.isDeviceLogined({
                deviceId: device.deviceId,
                success:function (deviceLoginInfo) {
                    seq.resolve({
                        device: device,
                        loginInfo: deviceLoginInfo,
                    });
                },
                fail:function (e) {
                    seq.reject(e)
                }
            })
        }).then(function (seq,device) {
            if(device.loginInfo.isLogined){
                //已登录，退出
                $m.util.success(param,device.device.deviceId);
            }else{
                //未登录
                if( (!param.password || param.password==="") && $m._ui && $m._ui.loginDevice){
                    //UI层输入密码
                    $m._ui.loginDevice({
                        device:device.device,
                        success:function (password) {
                            param.password=password;
                            seq.resolve();
                        },
                        fail:function (e) {
                            seq.reject(e)
                        }
                    })
                }
                else {
                    seq.resolve();
                }
            }
        }).then(function () {
            //执行登录
            var oldSucess=param.success
            param.success=function (){
                oldSucess(param.deviceId)
            }
            that.imp.loginDevice(param);
        }).onerror(function (e) {
            $m.util.fail(param,e);
        }).run();
    };

